package de.local.tapoviewer;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.view.*;
import android.widget.*;
import androidx.media3.common.Player;
import androidx.media3.exoplayer.ExoPlayer;
import androidx.recyclerview.widget.RecyclerView;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.platform.app.InstrumentationRegistry;
import org.junit.*;
import org.junit.runner.RunWith;
import java.io.*;
import java.lang.reflect.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.Assert.*;

@RunWith(AndroidJUnit4.class)
@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
public class MediaGalleryDeviceTest {
    private Instrumentation instrumentation;private Context context;private File photo,clip;private String prefix;private final List<Activity> screens=new ArrayList<>();
    @Before public void prepare()throws Exception{instrumentation=InstrumentationRegistry.getInstrumentation();context=instrumentation.getTargetContext();prefix="GalleryTest_"+UUID.randomUUID().toString().replace("-","");photo=LocalMedia.create(context,prefix,".jpg");Bitmap picture=Bitmap.createBitmap(1280,720,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(picture);canvas.drawColor(Color.rgb(8,23,43));Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);paint.setColor(ViewerStyle.ACCENT);canvas.drawCircle(640,360,180,paint);paint.setColor(Color.WHITE);paint.setTextSize(58);canvas.drawText("Aufnahmen · Foto",370,580,paint);try(OutputStream out=new FileOutputStream(photo)){assertTrue(picture.compress(Bitmap.CompressFormat.JPEG,90,out));}picture.recycle();CountDownLatch done=new CountDownLatch(1);String[] error={null};PreviewRecorder recorder=new PreviewRecorder(context,prefix,(file,message)->{clip=file;error[0]=message;done.countDown();});for(int i=0;i<15;i++){Bitmap frame=Bitmap.createBitmap(640,360,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(frame);c.drawColor(Color.rgb(8,23,43));paint.setColor(ViewerStyle.ACCENT);c.drawCircle(80+i*28,180,55,paint);paint.setColor(Color.WHITE);paint.setTextSize(30);c.drawText("Aufnahmen · Video",180,310,paint);recorder.frame(frame);long until=System.currentTimeMillis()+10000;while(recorder.busy&&System.currentTimeMillis()<until)Thread.sleep(20);}recorder.finish();assertTrue(done.await(15,TimeUnit.SECONDS));assertNull(error[0]);assertNotNull(clip);}
    @After public void clean(){for(int i=screens.size()-1;i>=0;i--){Activity screen=screens.get(i);instrumentation.runOnMainSync(screen::finish);}instrumentation.waitForIdleSync();for(File file:LocalMedia.list(context))if(file.getName().startsWith(prefix+"_"))LocalMedia.delete(context,file);}
    @Test public void thumbnailsAndGalleryOpenFullSizePhoto()throws Exception{for(File file:new File[]{photo,clip}){Bitmap thumb=MediaImages.load(file,480,270);assertNotNull(thumb);assertTrue(thumb.getWidth()<=1280);thumb.recycle();}MediaLibraryActivity library=(MediaLibraryActivity)start(MediaLibraryActivity.class,null);RecyclerView grid=(RecyclerView)field(library,"grid");await(()->grid.getChildCount()>=2);await(()->((ImageView)((android.view.ViewGroup)grid.getChildAt(0)).getChildAt(0)).getDrawable()!=null);assertFalse(contains(library.getWindow().getDecorView(),"Teilen"));assertFalse(contains(library.getWindow().getDecorView(),"Schnappschüsse"));assertTrue(contains(library.getWindow().getDecorView(),"Aufnahmen"));capture(library,"gallery-4.2.png");Instrumentation.ActivityMonitor monitor=instrumentation.addMonitor(MediaViewerActivity.class.getName(),null,false);try{instrumentation.runOnMainSync(()->{for(int i=0;i<grid.getChildCount();i++){View card=grid.getChildAt(i);if(card.getContentDescription().toString().endsWith(photo.getName())){card.performClick();return;}}throw new AssertionError("Test photo card missing");});MediaViewerActivity viewer=(MediaViewerActivity)instrumentation.waitForMonitorWithTimeout(monitor,5000);assertNotNull(viewer);screens.add(viewer);await(()->field(viewer,"image")!=null);assertEquals(View.GONE,((View)field(viewer,"play")).getVisibility());capture(viewer,"gallery-photo-4.2.png");}finally{instrumentation.removeMonitor(monitor);}}
    @Test public void videoControlsPauseSeekAndZoomWithRemote()throws Exception{MediaViewerActivity viewer=(MediaViewerActivity)start(MediaViewerActivity.class,clip);await(()->((ExoPlayer)field(viewer,"player")).getPlaybackState()==Player.STATE_READY);await(()->hasVideoFrame(viewer));key(viewer,KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE);instrumentation.runOnMainSync(()->{try{assertFalse(((ExoPlayer)field(viewer,"player")).getPlayWhenReady());}catch(Exception e){throw new RuntimeException(e);}});key(viewer,KeyEvent.KEYCODE_MEDIA_FAST_FORWARD);key(viewer,KeyEvent.KEYCODE_MEDIA_REWIND);key(viewer,KeyEvent.KEYCODE_CHANNEL_UP);assertEquals(1,field(viewer,"zoom"));key(viewer,KeyEvent.KEYCODE_DPAD_CENTER);assertEquals(true,field(viewer,"confirm"));assertEquals(View.GONE,((View)field(viewer,"chrome")).getVisibility());key(viewer,KeyEvent.KEYCODE_DPAD_RIGHT);assertTrue((Float)field(viewer,"x")<0);key(viewer,KeyEvent.KEYCODE_BACK);assertEquals(0,field(viewer,"zoom"));key(viewer,KeyEvent.KEYCODE_DPAD_CENTER);assertEquals(View.VISIBLE,((View)field(viewer,"chrome")).getVisibility());capture(viewer,"gallery-video-4.2.png");}
    private Activity start(Class<?> type,File file){Intent intent=new Intent(context,type).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);if(file!=null)intent.putExtra("file",file.getName());Activity screen=instrumentation.startActivitySync(intent);screens.add(screen);instrumentation.waitForIdleSync();return screen;}
    private void key(Activity screen,int key){instrumentation.runOnMainSync(()->{screen.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,key));screen.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_UP,key));});instrumentation.waitForIdleSync();}
    private Object field(Object screen,String name)throws Exception{Field field=screen.getClass().getDeclaredField(name);field.setAccessible(true);return field.get(screen);}
    private interface Condition{boolean ready()throws Exception;}
    private void await(Condition condition)throws Exception{long deadline=System.currentTimeMillis()+15000;while(System.currentTimeMillis()<deadline){boolean[] ready={false};instrumentation.runOnMainSync(()->{try{ready[0]=condition.ready();}catch(Exception e){throw new RuntimeException(e);}});if(ready[0])return;Thread.sleep(100);}fail("UI/media did not become ready");}
    private boolean contains(View view,String text){if(view instanceof TextView&&((TextView)view).getText().toString().trim().equals(text))return true;if(view instanceof android.view.ViewGroup)for(int i=0;i<((android.view.ViewGroup)view).getChildCount();i++)if(contains(((android.view.ViewGroup)view).getChildAt(i),text))return true;return false;}
    private boolean hasVideoFrame(MediaViewerActivity viewer)throws Exception{View surface=((androidx.media3.ui.PlayerView)field(viewer,"video")).getVideoSurfaceView();if(!(surface instanceof TextureView)||!((TextureView)surface).isAvailable())return false;Bitmap bitmap=((TextureView)surface).getBitmap(160,90);if(bitmap==null)return false;try{return (bitmap.getPixel(80,45)&0x00ffffff)!=0;}finally{bitmap.recycle();}}
    private void capture(Activity screen,String name){try{await(screen::hasWindowFocus);Thread.sleep(400);}catch(Exception e){throw new RuntimeException(e);}instrumentation.waitForIdleSync();Bitmap bitmap=instrumentation.getUiAutomation().takeScreenshot();assertNotNull(bitmap);try(OutputStream out=new FileOutputStream(new File(context.getCacheDir(),name))){assertTrue(bitmap.compress(Bitmap.CompressFormat.PNG,100,out));}catch(Exception e){throw new RuntimeException(e);}finally{bitmap.recycle();}}
}
